<script lang="ts">
 import {enhance} from '$app/forms';import {money,type FinanceWorkspace} from '$lib/finance';import type {OperationsWorkspace} from '$lib/server/finance-operations';
 let {data,form}:{data:{workspace:FinanceWorkspace;operations:OperationsWorkspace;basePath:string};form?:{message?:string;failed?:boolean}|null}=$props();const o=$derived(data.operations),w=$derived(data.workspace),s=$derived(o.state);
 const jobName=(id:string)=>w.jobChoices.find(j=>j.id===id)?.name||id;const vendorName=(id:string)=>w.vendors.find(v=>v.id===id)?.name||id;
</script>
<svelte:head><title>Finance operations · TurnKeyOps</title></svelte:head>
<div class="operations"><header><h1>Review costs. Prepare close.</h1><a href={`${data.basePath}/finance/construction`}>Construction finance</a><a href={`${data.basePath}/finance`}>Accounting workspace</a></header><p>Authorized Finance owner workspace. Labor cost rates and compliance records require financial control permission.</p>{#if form?.message}<p role={form.failed?'alert':'status'}>{form.message}</p>{/if}
<section><h2>Close readiness</h2>{#each o.close as period}<article><h3>{period.id}</h3>{#each period.issues as issue}<p>Blocker: {issue}</p>{:else}<p>No operations blockers recorded.</p>{/each}</article>{/each}<details><summary>Review checklist item</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="close-task"/><label>Period<select name="periodId">{#each w.state.periods as p}<option value={p.id}>{p.id}</option>{/each}</select></label><label>Checklist key<input name="key" required/></label><label>Task description<input name="description" required/></label><label><span><input type="checkbox" name="required"/>Required close blocker</span></label><label><span><input type="checkbox" name="complete"/>Reviewed complete</span></label><label>Evidence<input name="reason" required/></label><button>Record checklist review</button></form></details>{#each s.closeTasks as task}<p>{task.periodId} · {task.description} · {task.complete?'Complete':'Incomplete'} · {task.required?'Required':'Warning'}</p>{/each}</section>
<section><h2>AP retainage</h2><details><summary>Configure dedicated retainage payable account</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="ap-retainage-policy"/><label>Retainage liability<select name="offsetAccount">{#each w.state.accounts.filter(a=>a.type==='LIABILITY') as account}<option value={account.code}>{account.code} · {account.name}</option>{/each}</select></label><label>Policy authorization<input name="reason" required/></label><button>Save AP retainage policy</button></form></details>{#each o.apRetainage??[] as bill}<article><h3>{bill.number} · {vendorName(bill.vendorId)}</h3><p>Gross {money(bill.gross)} · Net ordinary AP {money(bill.net)} · Withheld {money(bill.withheld)} · Remaining retained payable {money(bill.held)}</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="targetId" value={bill.id}/><label>Operation<select name="action"><option value="release-ap-retainage">Release retained payable to ordinary AP</option><option value="credit-retained-bill">Credit retained bill (gross credit)</option></select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required/></label><label>Posting date<input name="date" type="date" required/></label><label>Unique source reference<input name="sourceKey" required/></label><label>Release / credit authorization<input name="reason" required/></label><button>Post reviewed AP retainage transaction</button></form></article>{:else}<p>No retained vendor bills.</p>{/each}</section>
<section><h2>Labor time approval</h2><a href={`${data.basePath}/finance/operations/export?type=payroll`}>Export posted labor for payroll integration CSV</a>{#each s.time as time}<article><h3>{jobName(time.jobId)} · {time.date}</h3><p>Employee {time.employeeId} · {time.hours} hours · {time.status}{time.rateSnapshot!==undefined?` · Cost rate ${money(time.rateSnapshot)}`:''}</p>{#if ['SUBMITTED','APPROVED'].includes(time.status)}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="targetId" value={time.id}/><label>Accrued labor liability account<select name="offsetAccount">{#each w.state.accounts.filter(a=>a.type==='LIABILITY'&&a.active) as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Approval evidence<input name="reason" required/></label><button name="action" value={time.status==='SUBMITTED'?'approve-time':'post-time'}>{time.status==='SUBMITTED'?'Approve time and snapshot rate':'Post approved Job labor cost'}</button>{#if time.status==='SUBMITTED'}<button name="action" value="reject-time">Reject submitted time</button>{/if}</form>{/if}</article>{:else}<p>No labor entries submitted.</p>{/each}<details><summary>Record labor time</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="submit-time"/><label>Employee user ID<select name="employeeId" required>{#each o.employees??[] as employee}<option value={employee.employeeId}>{employee.employeeId}</option>{/each}</select></label><label>Job<select name="jobId">{#each w.jobChoices as j}<option value={j.id}>{j.name}</option>{/each}</select></label><label>Work date<input type="date" name="date" required/></label><label>Earnings classification<select name="earningsClass"><option value="REGULAR">Regular</option><option value="OVERTIME">Overtime</option><option value="DOUBLE_TIME">Double time</option></select></label><label>Hours<input type="number" min="0.01" max="24" step="0.01" name="hours" required/></label><label>Labor cost code<select name="costCode">{#each w.state.costCodes.filter(c=>c.category==='LABOR') as code}<option value={code.code}>{code.name}</option>{/each}</select></label><label>Unique time source reference<input name="sourceKey" required/></label><label>Source evidence<input name="reason" required/></label><button>Submit labor time</button></form></details><details><summary>Secure labor cost rates</summary>{#each s.rates as rate}<p>{rate.employeeId} · Effective {rate.effectiveDate} · Base {money(rate.hourlyRate)} + burden {money(rate.burdenRate)}</p>{/each}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="labor-rate"/><label>Employee user ID<select name="employeeId" required>{#each o.employees??[] as employee}<option value={employee.employeeId}>{employee.employeeId}</option>{/each}</select></label><label>Effective date<input name="date" type="date" required/></label><label>Hourly cost rate<input name="hourlyRate" type="number" min="0.01" step="0.01" required/></label><label>Hourly burden<input name="burdenRate" type="number" min="0" step="0.01" value="0" required/></label><label>Rate authorization<input name="reason" required/></label><button>Save effective labor rate</button></form></details></section>
<section><h2>Accruals & recurring journals</h2><p>Scheduled reversals: {s.reversalPolicy?.enabled?'Enabled by authorized owner':'Disabled'}. Worker attempts preserve diagnostics and closed-period failures for review.</p><details><summary>Authorize scheduled accrual reversals</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="reversal-policy"/><label><span><input type="checkbox" name="enabled" checked={s.reversalPolicy?.enabled}/>Enable deterministic due reversal worker</span></label><label>Owner scheduling authorization<input name="reason" required/></label><button>Save reversal schedule policy</button></form></details>{#each s.reversalAttempts??[] as attempt}<p>{attempt.attemptDate} · {attempt.accrualId} · {attempt.status} · {attempt.reason}</p>{/each}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="generate-due-reversals"/><label>Reverse accruals due through<input name="date" type="date" required/></label><label>Batch reversal authorization<input name="reason" required/></label><button>Generate due linked reversals</button></form>{#each [...(s.accrualDrafts??[]).map(a=>({...a,status:'DRAFT'})),...s.accruals] as accrual}<article><h3>{accrual.description}</h3><p>Posted {accrual.date} · Reversal due {accrual.reversalDate} · {accrual.reversalJournalId?'Reversed':'Awaiting reversal'}</p>{#if !accrual.reversalJournalId}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value={accrual.status==='DRAFT'?'post-accrual-draft':'reverse-accrual'}/><input type="hidden" name="targetId" value={accrual.id}/><label>Reversal authorization<input name="reason" required/></label><button>{accrual.status==='DRAFT'?'Post reviewed accrual draft':'Post linked reversal'}</button></form>{/if}</article>{/each}
<details><summary>Create reviewed accrual or recurring template</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><label>Operation<select name="action"><option value="draft-accrual">Draft accrual with reversal date</option><option value="recurring-template">Save recurring template</option></select></label><label>Description<input name="description" required/></label><label>Accrual / schedule start<input name="date" type="date" required/></label><label>Reversal / schedule end<input name="endDate" type="date" required/></label><label>Journal lines (account, debit, credit, optional Job ID, cost code, category)<textarea name="lines" rows="4" required></textarea></label><label>Posting authorization / evidence<input name="reason" required/></label><button>Record reviewed journal operation</button></form></details>{#each s.recurring as template}<article><h3>{template.description}</h3><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="post-recurring"/><input type="hidden" name="targetId" value={template.id}/><label>Posting date<input name="date" type="date" required/></label><label>Posting authorization<input name="reason" required/></label><button>Post recurring journal for month</button></form></article>{/each}</section>
<section><h2>Vendor compliance</h2><a href={`${data.basePath}/finance/operations/export?type=1099&taxYear=${o.taxYear||new Date().getFullYear()}`}>Export tax-year 1099 payment sources CSV</a><form method="GET"><label>1099 report tax year<input name="taxYear" type="number" min="2000" max="2100" value={o.taxYear||new Date().getFullYear()} required/></label><button>Review tax year payments</button></form>{#each s.vendors as vendor}<p>{vendorName(vendor.vendorId)} · W-9 {vendor.w9Status} · Insurance {vendor.insuranceExpiry||'Unknown'} · License {vendor.licenseExpiry||'Unknown'} · {vendor.eligible1099?'1099 eligible':'1099 not classified'}</p>{/each}<details><summary>Review vendor compliance</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="vendor-compliance"/><label>Vendor<select name="vendorId">{#each w.vendors as vendor}<option value={vendor.id}>{vendor.name}</option>{/each}</select></label><label>W-9 status<select name="w9Status"><option>MISSING</option><option>REQUESTED</option><option>RECEIVED</option></select></label><label>Insurance expires<input name="insuranceExpiry" type="date"/></label><label>License expires<input name="licenseExpiry" type="date"/></label><label>Classification<input name="classification" required/></label><label><span><input type="checkbox" name="eligible1099"/>1099 eligible</span></label><label>Evidence attachment IDs (comma separated)<input name="attachmentIds"/></label><label>Review evidence<input name="reason" required/></label><button>Record compliance review</button></form></details><details><summary>1099 payment source records</summary><pre>{JSON.stringify(o.vendorPayments1099,null,2)}</pre></details></section>
<section><h2>Bank feed & split matching</h2><p>Live pulls require a deployment-configured provider and tenant account allowlist. No credentials are entered in this workspace.</p><details><summary>Configure tenant bank connection</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="bank-connection"/><label>Configured provider ID<input name="providerId" value={s.bankConnection?.providerId||''} required/></label><label>Provider account reference<input name="accountReference" value={s.bankConnection?.accountReference||''} required/></label><label>Finance cash account<select name="cashAccountId">{#each w.state.cashAccounts as account}<option value={account.id}>{account.name}</option>{/each}</select></label><label><span><input type="checkbox" name="enabled" checked={s.bankConnection?.enabled}/>Enable approved provider connection</span></label><label>Connection authorization<input name="reason" required/></label><button>Save tenant bank connection</button></form></details>{#if s.bankConnection?.enabled}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="pull-bank-feed"/><label>Provider pull review evidence<input name="reason" required/></label><button>Pull configured bank feed</button></form>{/if}<details><summary>Import OFX / QFX statement</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="ingest-bank-ofx"/><label>Statement cash account<select name="cashAccountId">{#each w.state.cashAccounts as account}<option value={account.id}>{account.name}</option>{/each}</select></label><label>Stable bank/account source key<input name="sourceKey" required/></label><label>OFX / QFX statement text<textarea name="lines" rows="5" required></textarea></label><label>Statement review evidence<input name="reason" required/></label><button>Import reviewed OFX statement</button></form></details><details><summary>Import normalized bank transactions</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="ingest-bank"/><label>Bank account<select name="cashAccountId">{#each w.state.cashAccounts as account}<option value={account.id}>{account.name}</option>{/each}</select></label><label>Import source reference<input name="sourceKey" required/></label><label>Rows (external ID, date, signed amount, reference)<textarea name="lines" rows="4" required></textarea></label><label>Import review evidence<input name="reason" required/></label><button>Ingest reviewed feed</button></form></details><details><summary>Review a split bank match</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="match-bank-split"/><label>Bank transaction<select name="targetId">{#each w.state.bankTransactions as tx}<option value={tx.id}>{tx.date} · {money(tx.amount)} · {tx.reference}</option>{/each}</select></label><label>Matched posted journal IDs and signed amounts (one per row)<textarea name="lines" rows="4" required></textarea></label><label>Human match review evidence<input name="reason" required/></label><button>Confirm reviewed split match</button></form></details></section>
<section><h2>Fixed asset register</h2><details><summary>Capitalize a recorded purchase</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={o.version}/><input type="hidden" name="action" value="capitalize-asset"/><label>Source purchase journal<select name="targetId">{#each w.state.journals as journal}<option value={journal.id}>{journal.date} · {journal.memo}</option>{/each}</select></label><label>Original expense account<select name="offsetAccount">{#each w.state.accounts.filter(a=>['EXPENSE','COST_OF_GOODS_SOLD'].includes(a.type)) as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Fixed asset account<select name="assetAccount">{#each w.state.accounts.filter(a=>a.type==='ASSET') as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Asset description<input name="description" required/></label><label>Asset class<input name="assetClass" required/></label><label>Acquisition date<input name="date" type="date" required/></label><label>Capitalized purchase cost<input name="cost" type="number" min="0.01" step="0.01" required/></label><label>In service<input name="inServiceDate" type="date"/></label><label>Assigned location<input name="location" required/></label><label>Related equipment ID<input name="equipmentId"/></label><label>Capitalization policy approval<input name="reason" required/></label><button>Capitalize reviewed purchase expense</button></form></details>{#each s.assets as asset}<p>{asset.description} · {money(asset.cost)} · {asset.status} · {asset.id}</p>{:else}<p>No fixed assets recorded.</p>{/each}</section>
</div>
<style>.operations{padding:1.5rem;color:var(--text-primary,#183039);display:grid;gap:1rem;max-width:100%}header{display:flex;flex-wrap:wrap;gap:1rem;align-items:center}section{background:var(--bg-card,#fff);border:1px solid var(--border-color,#b9c8ca);border-radius:.75rem;padding:1.25rem;min-width:0}h1{font-size:1.8rem}h2{font-size:1.3rem}h3{font-size:1rem}h1,h2,h3{font-weight:650}p{line-height:1.6;margin:.7rem 0}form{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:1rem 0}label{display:flex;flex-direction:column;gap:.4rem}input,select,textarea,button{border:1px solid var(--border-color,#b9c8ca);border-radius:.4rem;background:transparent;color:inherit;padding:.65rem;max-width:100%;min-width:0}button{min-height:44px;align-self:end;background:#a94b0b;color:white}input[type=checkbox]{width:1rem;height:1rem}summary{padding:.6rem 0;cursor:pointer;font-weight:600}article{border-bottom:1px solid var(--border-color,#b9c8ca);padding:.5rem 0}a{text-decoration:underline}pre{overflow:auto;max-width:100%}:is(input,select,textarea,button,summary,a):focus-visible{outline:3px solid #16817c;outline-offset:3px}:global([data-theme=dark]) .operations{color:#e0ebed}:global([data-theme=dark]) .operations section{background:#132b34;border-color:#56717a}@media(max-width:600px){.operations{padding:.75rem}form{grid-template-columns:1fr}}</style>
